select

from BLACKLIST


        and CARD_ID = #{cardId,jdbcType=VARCHAR}


        and THIRD_USER_ID = #{thirdUserId,jdbcType=VARCHAR}


        and STATUS = #{status,jdbcType=VARCHAR}


        and CHANNEL_SYNC_STATUS = #{channelSyncStatus,jdbcType=VARCHAR}


        and CREATE_TIME >= TO_TIMESTAMP(#{createTimeBegin,jdbcType=VARCHAR}, 'YYYY-MM-DD HH24:MI:SS')


        and CREATE_TIME <= TO_TIMESTAMP(#{createTimeEnd,jdbcType=VARCHAR}, 'YYYY-MM-DD HH24:MI:SS')


order by CREATE_TIME desc, ID desc

